"""Report the fixed post-hoc six-source competence diagnostic, keeping primary results separate."""
import csv,gzip,hashlib,json,statistics,subprocess
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw,ImageFont
from exp20261011_train_report import add_70mm_metric
ROOT=Path(__file__).resolve().parents[1]
OUT=Path('/var/tmp/typhon-research-20261011/broad-pt/source-competence')
FOLDER=OUT/'evaluation/broad-pt-12000'
def dump(p,v):p.write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
def records(p):
 with gzip.open(p,'rt') as f:return [json.loads(x) for x in f]
def main():
 complete=json.loads((FOLDER/'complete.json').read_text());assert complete['completed'] and complete['trials']==6 and complete['runtime_errors']==0
 rows=json.loads((FOLDER/'summary.json').read_text());assert len(rows)==6 and all(not r['errors'] for r in rows)
 assert json.loads((FOLDER/'reload-verification.json').read_text())['action_max_error']==0
 videos=[];metrics=[]
 for r in rows:
  folder=FOLDER/r['id'];add_70mm_metric(FOLDER,r);trace=records(folder/'controller_trace.jsonl.gz');traj=records(folder/'trajectory.jsonl.gz');by_step={x['step']:x for x in traj};assert all(x['step'] in by_step for x in trace)
  truth=[by_step[x['step']]['truth'] for x in trace];obj=np.array([x['object_position_m'] for x in truth]);eef=np.array([x['eef_position_m'] for x in truth]);target=np.array([x['target'] for x in trace]);gripper=target[:,9]
  raw=np.array([by_step[x['step']]['requested_action'] for x in trace]);applied=np.array([by_step[x['step']]['applied_action'] for x in trace])
  np.testing.assert_array_equal(np.where(gripper>.5,1.0,-1.0),raw[:,-1])
  r.update(target_close_command_steps=int((gripper>.5).sum()),minimum_gripper_probability=float(gripper.min()),maximum_gripper_probability=float(gripper.max()),closest_commanded_target_to_object_centre_mm=float(np.linalg.norm(target[:,:3]-obj,axis=1).min()*1000),closest_executed_eef_to_object_centre_mm=float(np.linalg.norm(eef-obj,axis=1).min()*1000),raw_applied_changed_steps=int(np.any(np.abs(raw-applied)>1e-10,axis=1).sum()))
  video=folder/'rollout.mp4';info=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','v:0','-show_entries','stream=nb_frames,width,height,duration','-of','json',str(video)],text=True))['streams'][0];assert int(info['nb_frames'])>1
  cp=subprocess.run(['ffmpeg','-v','error','-i',str(video),'-f','null','-'],capture_output=True,text=True);assert cp.returncode==0 and not cp.stderr
  videos.append({'path':str(video),'full_decode_passed':True,**info})
  metrics.append({k:r[k] for k in ['id','source_demo_id','seed','success','supported_lift_10mm_3steps','bilateral_lift_70mm_3steps','footprint_inside_target','operational_placement','position_error_mm','initial_yaw_error_deg','final_yaw_error_deg','yaw_error_reduction_deg','maximum_lift_above_initial_mm','target_close_command_steps','closest_executed_eef_to_object_centre_mm','closest_commanded_target_to_object_centre_mm','raw_applied_changed_steps','wall_seconds']})
 summary={'scope':'Post-hoc source competence, all six exact P_train scenes; fixed12k checkpoint, seed7417, unchanged native O2/controller/1500steps, no harness. Not a heldout comparison or evidence of improvement against another model.','trials':6,'strict_successes':sum(r['success'] for r in rows),'supported_lift_10mm_3steps':sum(r['supported_lift_10mm_3steps'] for r in rows),'supported_lift_70mm_3steps':sum(r['bilateral_lift_70mm_3steps'] for r in rows),'inside_square':sum(r['footprint_inside_target'] for r in rows),'operational_placements':sum(r['operational_placement'] for r in rows),'mean_position_error_mm':statistics.mean(r['position_error_mm'] for r in rows),'mean_final_yaw_error_deg':statistics.mean(r['final_yaw_error_deg'] for r in rows),'all_videos_decoded':len(videos),'outcomes':rows}
 dump(OUT/'validation_summary.json',summary);dump(OUT/'video-validation.json',videos)
 with (OUT/'episodes.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(metrics[0]));w.writeheader();w.writerows(metrics)
 lines=['# Post-hoc source competence of fixed broad12k','','The primary paired holdout comparison remains unchanged. After observing zero holdout grasps despite good expert-state action fit, we froze this separate diagnostic before inference: all six exact P_train initial configurations, seed7417, the fixed12k weights, and the same native O2/H30/1500-step interface. No model selection, tuning, extra training, harness, or replay of expert commands occurs.','',f"The model achieved {summary['supported_lift_10mm_3steps']}/6 supported pickups, {summary['operational_placements']}/6 released stable placements in the square, and {summary['strict_successes']}/6 strict successes on its source scenes. These are in-distribution development results, not heldout generalization.",'','| Take | Pickup ≥10mm | Pickup ≥70mm | In square | Released stable placement | Strict success | Position residual | Initial required yaw | Final yaw residual |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in metrics:lines.append(f"| {r['source_demo_id']} | {int(r['supported_lift_10mm_3steps'])} | {int(r['bilateral_lift_70mm_3steps'])} | {int(r['footprint_inside_target'])} | {int(r['operational_placement'])} | {int(r['success'])} | {r['position_error_mm']:.2f} mm | {r['initial_yaw_error_deg']:.2f}° | {r['final_yaw_error_deg']:.2f}° |")
 lines+=['','Pickup uses simultaneous bilateral contact plus lift for three consecutive control steps. Strict success includes the original 15mm goal-centre position tolerance as well as whole-footprint containment, 10-degree yaw/upright tolerance, release, height and stability. A fully contained, released placement can therefore miss the stricter centre tolerance. These thresholds were not changed after results.','','The fixed12k model can issue closure, lift and in some cases finish the full task when initialized on a source scene. This rules out a universal inability of the checkpoint/controller pair to grasp. It does not resolve the zero-grasp failure on the three P_validation families, or show that this model generalizes. Source failures and successes are all retained. The primary results remain 0/6 heldout grasps and strict successes for each of narrow3k, broad3k and broad12k.','','All six videos fully decoded; fresh-process reload exactly matched the saved inference probe. Raw model chunks, RGB observations, command histories, joint/controller traces, scene configs and independent scorer outputs are retained under evaluation/broad-pt-12000/. The extra trace statistics in episodes.csv are exploratory diagnostic quantities; EEF-to-centre distance is not a new grasp criterion.','','Reproduction from the project root after a GPU slot is assigned (a populated result directory refuses replacement):','','```bash','.venv-sim/bin/python scripts/exp20261011_train_source_competence.py prepare','.venv-sim/bin/python scripts/exp20261011_train_source_competence.py evaluate --method broad-pt-12000','.venv-sim/bin/python scripts/exp20261011_train_source_report.py','```','']
 lines+=['## Visual and coverage checks','','![Illustrative source cases](figures/representative-source-cases.jpg)','','The saved sheet contrasts one held-stall, one strict success, and the source placement that misses only the centre tolerance. The middle panels are the nearest saved model observation to maximum lift, with timing documented in figures/visual-provenance.json. These are illustrative post-hoc selections; all six outcomes remain in the table. Agent visual inspection corroborates a held brick for0001 and released in-square placements for0002/0005; this is not human validation of every episode.','','![Frozen initial-state coverage](figures/initial-state-coverage.png)','','All three development holdout XY starts fall outside the convex hull of the six source starts. Their nearest-source XY distances are119.9mm,51.9mm,313.7mm for0006/0014/0016. Their nearest-source circular yaw differences are69.7,2.18,85.7degrees respectively. Position and yaw nearest neighbours can be different examples. This descriptive state coverage does not prove the cause of failure, but it establishes that the heldout panel requires extrapolation beyond source positions rather than only repetition of familiar poses. Exact values and coordinates are in ../state-coverage.json.','','Regenerate these CPU visuals with ` .venv-sim/bin/python scripts/exp20261011_train_source_visuals.py ` from the project root.']
 (OUT/'SOURCE_COMPETENCE_REPORT.md').write_text('\n'.join(lines))
 print(json.dumps({k:v for k,v in summary.items() if k!='outcomes'},indent=2))
if __name__=='__main__':main()
